//! Evaluator parity with the Python adapter over many candidate suites files (tests/fixtures/evaluator/ev_golden.json,
//! generated by the Python EvaluatorAdapter with gen_ev_golden.py): validate_config (schema only, then with a cached
//! datasets view) and suites() must give the same results, or raise the same Python exception.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

#[path = "evaluator_helpers.rs"]
mod helpers;

use helpers::*;
use indexmap::IndexMap;
use nemo_console::adapters::base::{AdapterError, SystemAdapter};
use serde_json::{Value, json};

fn raised(e: &AdapterError) -> Value {
    json!({"raised": {"class": e.py_class(), "message": e.to_string()}})
}

#[tokio::test]
async fn test_validate_and_suites_match_the_python_adapter() {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/evaluator/ev_golden.json"
    );
    let golden: Value = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    let cases = golden["cases"].as_array().unwrap();
    assert!(cases.len() > 500);
    let f = Fx::new().await;
    let mut failures = Vec::new();
    for c in cases {
        let text = c["input"].as_str().unwrap();
        let a = f.adapter_with(&FakeRunner::new(), Some(text), true, None);
        let v1 = match a.validate_config("suites.yaml", text).await {
            Ok(v) => serde_json::to_value(v).unwrap(),
            Err(e) => raised(&e),
        };
        let mut view = IndexMap::new();
        view.insert("gsm8k".to_owned(), false);
        view.insert("mmlu".to_owned(), true);
        a.set_cached_view(Some(view));
        let v2 = match a.validate_config("suites.yaml", text).await {
            Ok(v) => serde_json::to_value(v).unwrap(),
            Err(e) => raised(&e),
        };
        let s = match a.suites() {
            Ok((suites, errors)) => {
                let m: serde_json::Map<String, Value> = suites
                    .iter()
                    .map(|(k, s)| (k.clone(), json!({"model": s.model, "benches": s.benches})))
                    .collect();
                json!({"suites": m, "errors": errors})
            }
            Err(e) => raised(&e),
        };
        for (what, got, want) in [
            ("validate", v1, &c["validate"]),
            ("validate_cached", v2, &c["validate_cached"]),
            ("suites", s, &c["suites"]),
        ] {
            if got != *want {
                failures.push(format!("{what} of {text:?}\n  want {want}\n  got  {got}"));
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} differences:\n{}",
        failures.len(),
        failures
            .iter()
            .take(15)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}
